import{_ as l,l as i,o as e,c as s,v as t,p,x as r,d as h,i as n,S as d}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"每层成本与每晶圆成本","description":"","frontmatter":{"title":"每层成本与每晶圆成本","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/cost-per-layer-wafer.md","filePath":"litho/cost-per-layer-wafer.md","lastUpdated":1789023840000}'),c={name:"litho/cost-per-layer-wafer.md"};function E(_,a,m,A,f,u){const o=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="每层成本与每晶圆成本" tabindex="-1">每层成本与每晶圆成本 <a class="header-anchor" href="#每层成本与每晶圆成本" aria-label="Permalink to &quot;每层成本与每晶圆成本&quot;">​</a></h1><div class="epigraph"><p>晶圆成本是各层光刻–刻蚀–薄膜之和再加测试；比较 EUV 与多重必须按层加总，不能按「用没用 EUV」一句话。</p><footer>—— 对照晶圆成本结构与 per-layer litho cost 的产业讨论；不编造美元表</footer></div><p><a href="/litho/irds-roadmap">上一课</a>给出需求骨架。缺口是钱。本课钉每层成本与每晶圆成本。EUV 与多重的交叉点，留给[下一课](/litho/euv-vs-multipattern-cost-crossover）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>一层成本 ≈ 扫描机折旧与维护 + 轨道化学 + 掩模摊销 + 计量 + 重工税 + 刻蚀/薄膜若算进「图形化模块」。EUV 层：光源、pellicle、剂量时间、抗蚀剂、掩模更贵，但张数可能更少。浸没多重：扫描机便宜些，过机次数、套刻、掩模张数把模块成本抬上去。晶圆成本还含非光刻（注入、CMP、清洗）。</p><p>缺口是<strong>按层模块账</strong>，不是节点名。不引用无来源的「EUV 晶圆 xx 美元」。</p><h3 id="掩模摊销随片量" tabindex="-1">掩模摊销随片量 <a class="header-anchor" href="#掩模摊销随片量" aria-label="Permalink to &quot;掩模摊销随片量&quot;">​</a></h3><p>工程 lot 掩模主导；量大后扫描机与胶主导。<a href="/litho/mask-cost-cycle">掩模成本</a> 已写。本课把它嵌进每晶圆。</p><p><span class="marginnote">wph 是单次过机。LELE 模块有效产能是 wph 除以次数再扣轨道刻蚀节拍。用标称 wph 去除以晶圆成本会乐观。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>建层表：每层曝光策略、过机次数、掩模数、计量密度。求和。灵敏度：剂量、pellicle 透过、重工率。与良率：低良率把所有成本摊到好片上，往往超过省一次曝光的钱。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>成本随步骤数近线性（机会缺陷也近线性增加机会），随随机剂量近超线性（wph 掉）。交叉点课将用这张结构，仍不填假数字。</p>',13)),(e(),p(d,null,{default:r(()=>[n(o,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20L%5B%22%E5%90%84%E5%B1%82%E6%A8%A1%E5%9D%97%E6%88%90%E6%9C%AC%22%5D%20--%3E%20W%5B%22%E6%AF%8F%E6%99%B6%E5%9C%86%22%5D%0A%20%20Y%5B%22%E8%89%AF%E7%8E%87%22%5D%20--%3E%20GOOD%5B%22%E6%AF%8F%E5%A5%BD%E7%89%87%22%5D%0A%20%20W%20--%3E%20GOOD%0A%20%20MASK%5B%22%E6%8E%A9%E6%A8%A1%E6%91%8A%E9%94%80%22%5D%20--%3E%20L%0A%20%20SCAN%5B%22%E6%89%AB%E6%8F%8F%E6%9C%BA%E5%B0%8F%E6%97%B6%22%5D%20--%3E%20L%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不给美元。不把测试、封装算进本课除非声明。成本不自动等于价格。</p><p>后课默认：比较必须按层模块；下一课专门画 EUV 单次 vs DUV 多重的交叉逻辑。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>每晶圆 = 层模块之和；图形化模块含掩模、过机、计量、重工。</li><li>标称 wph 必须除过机次数。</li><li>良率把成本摊到好片，常主导。</li><li>出处：per-layer litho cost 产业讨论结构；无来源报价不用。</li></ul>',5))])}const x=l(c,[["render",E]]);export{b as __pageData,x as default};
